cd /app/pyknotid && python3 - <<'PY'
from pathlib import Path
p = Path('pyknotid/representations/representation.py')
s = p.read_text()
old = "        g = planarity.networkx_graph(pg)\n\n\n        node_labels = {}"
new = """        g = planarity.networkx_graph(pg)

        # planarity >= 1.0 renamed the attributes returned by
        # networkx_graph; pyknotid 0.5.3 uses the older short names.
        for node, data in g.nodes(data=True):
            if 'pos' not in data and 'vertex_position' in data:
                data['pos'] = data['vertex_position']
            if 'start' not in data and 'vertex_start' in data:
                data['start'] = data['vertex_start']
            if 'end' not in data and 'vertex_end' in data:
                data['end'] = data['vertex_end']
        for node1, node2, data in g.edges(data=True):
            if 'pos' not in data and 'edge_position' in data:
                data['pos'] = data['edge_position']
            if 'start' not in data and 'edge_start' in data:
                data['start'] = data['edge_start']
            if 'end' not in data and 'edge_end' in data:
                data['end'] = data['edge_end']

        node_labels = {}"""
if old not in s:
    raise SystemExit('expected insertion point not found')
p.write_text(s.replace(old, new, 1))
print('patched', p)
